physical,AEROSKIN_SURF,1,STANDARD,,PHYSICAL,,highp,srgb-linear,306,1024,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,,,false,0,,0,2,2,1,0,1,0,0,2,0,0,0,0,1,0,0,0,0,8388752,8522771,srgb,atmo.inject+function (shader) {
  if (typeof ATMO !== 'undefined') ATMO.inject(shader);   // S4: the aerial-perspective sampler (a hook of its own loses the prototype's)
  // THE WEATHERING (G345): read here, at compile, and spliced in as text —
  // the same text for every material, so the one-program rule holds
  const W = aeroWx();
  const u = this.userData.aeroU;
  for (const k in u) shader.uniforms[k] = u[k];
  // the aeroplane-wide ones, BY REFERENCE: one write reaches every section
  const d = this.userData.aeroD;
  if (d) for (const k in d) shader.uniforms[k] = d[k];
  shader.vertexShader = shader.vertexShader
    .replace('#include <common>', AERO_PARS_VS + '\n#include <common>')
    .replace('#include <begin_vertex>',
             '#include <begin_vertex>\n' + AERO_MAIN_VS);
  shader.fragmentShader = shader.fragmentShader
    .replace('#include <common>',
             AERO_NMAT_FS + AERO_PARS_FS + (W ? W.AERO_WX_PARS_FS : '')
             + '\n#include <common>')
    .replace('#include <map_fragment>', AERO_HOLE_FS + AERO_ALBEDO_FS)
    .replace('#include <normal_fragment_maps>',
             AERO_SURFACE_FS + (W ? W.AERO_WX_SURF_FS : ''))
    // the clear coat loses what the dirt covers (G345)
    .replace('#include <lights_physical_fragment>',
             '#include <lights_physical_fragment>\n' + (W ? W.AERO_WX_CC_FS : ''))
    // THE CLEAR LAYER FOLLOWS THE RELIEF (G206). three's own chunk puts the
    // clearcoat on nonPerturbedNormal — the smooth mesh — so varnish over a rib
    // tape would reflect the sky as if the tape were not there. A clear coat
    // is brushed ONTO the tapes and the set panels; it takes the perturbed
    // normal. Inert on a Standard material: the include is not in its shader.
    .replace('#include <clearcoat_normal_fragment_begin>',
             '#ifdef USE_CLEARCOAT\n  vec3 clearcoatNormal = normal;\n#endif')   // USE_CLEARCOAT since r13x (W0.5a)
    .replace('#include <lights_fragment_end>', AERO_CABIN_FS);
}

